CREATE TABLE IF NOT EXISTS economic_decision_consensus (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL, assessment_score numeric(5,2) NOT NULL DEFAULT 0, network_score numeric(5,2) NOT NULL DEFAULT 0, evidence_trust numeric(5,2) NOT NULL DEFAULT 0, consensus_score numeric(5,2) NOT NULL DEFAULT 0, confidence text NOT NULL DEFAULT 'low', decision_state text NOT NULL DEFAULT 'needs_review', rationale jsonb NOT NULL DEFAULT '[]'::jsonb, recommended_actions jsonb NOT NULL DEFAULT '[]'::jsonb, created_by text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_decision_consensus_profile ON economic_decision_consensus(profile_id,created_at DESC);